import { Component, h, Prop, Host, Element, ComponentInterface } from '@stencil/core';
import classnames from 'classnames';
import { progressAnimation, convertNum2PX } from './utils';
import { ProgressStatus, ProgressType, ProgressSize } from './progress';
import { Slot, Slots } from '@src/framework/decorators';

const prefix = 'progress';

const CIRCLE_BORDER_WIDTH = {
  md: 8,
  sm: 4,
  xs: 2,
};
const CIRCLE_WIDTH = {
  md: 120,
  sm: 84,
  xs: 40,
};

const COLORS = {
  stroke: 'var(--ks-color-neutral-surface3)', // 底色
  success: 'var(--ks-color-success-fill)',
  error: 'var(--ks-color-error-fill)',
  warning: 'var(--ks-color-warning-fill)',
  default: 'var(--ks-color-primary-fill)',
};

/**
 * @slot helpText - Allows customization of the help text shown below the progress indicator. This slot is only rendered when the `variant` is `"bar"`.
 * @slot percentText - Allows customization of the percent label when `showPercentAndStatus` is `true` and the default text path is rendered.
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-progress',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsProgress implements ComponentInterface {
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Element() el: HTMLKsProgressElement;
  /** The current progress percentage, ranging from 0 to 100. This value indicates how much of the task has been completed. */
  @Prop() percent = 0;
  /** The status of the progress bar. Can be one of the following values: `"default"`, `"success"`, `"error"`, `"warning"`. In 'bar' mode, 'warning' has a distinct visual style. In 'ring' mode, 'warning' status visually defaults to the 'default' style for the ring and icon. */
  @Prop() status: ProgressStatus = 'default';
  /** The visual representation of the progress indicator. Can be one of the following values: `"bar"`, `"ring"`. */
  @Prop() variant: ProgressType = 'bar';
  /**
   * The size of the progress bar.
   * Can be one of the following values: `"md"`, `"sm"`, `"xs"`.
   */
  @Prop() size: ProgressSize = 'md';
  /** Indicates whether to show the trailing percent label or status icon. When `true`, the label area remains visible. */
  @Prop() showPercentAndStatus = true;
  /** Controls the rendered width of the bar variant and the diameter of the ring variant. */
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Prop() width: number | string;
  /** The slot for the help text. This slot is only rendered when the `variant` is 'bar'. */
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Slot({ slotname: 'helpText' }) private helpText: Slots;

  private renderPercentInfo() {
    if (!this.showPercentAndStatus) {
      return null;
    }
    const size = this.variant === 'ring' && this.size === 'xs' ? 'sm' : 'md';
    const status = this.variant === 'ring' && this.status === 'warning' ? 'default' : this.status;
    return (
      <div class={classnames(`${prefix}__label`, `${prefix}__label-${status}`)}>
        {(() => {
          switch (status) {
            case 'success':
              return <ks-status-icon variant="success" size={size} />;
            case 'error':
              return <ks-status-icon variant="error" size={size}></ks-status-icon>;
            case 'warning':
              return <ks-status-icon variant="warning" size={size}></ks-status-icon>;
            default:
              return (
                <slot name="percentText">
                  {`${Math.round(this.percent)}`}
                  <span>%</span>
                </slot>
              );
          }
        })()}
      </div>
    );
  }

  private renderProgressRing() {
    const { percent, size, status, variant, width } = this;
    const circleSize = typeof width === 'string' ? parseInt(width) : width || CIRCLE_WIDTH[size];
    const borderWidth = CIRCLE_BORDER_WIDTH[size] || CIRCLE_BORDER_WIDTH.md;
    const perimeter = 2 * Math.PI * (circleSize / 2 - borderWidth / 2);
    const strokeDasharray = `${(perimeter * percent) / 100} ${perimeter * (1 - percent / 100)}`;

    const circleBgColor = COLORS.stroke;
    const circleForeColor = status === 'warning' ? COLORS.default : COLORS[status];

    return (
      <div class={classnames(prefix, `${prefix}--${size}`, `${prefix}--${variant}`)} part="base">
        <svg width={circleSize} height={circleSize} viewBox={`0 0 ${circleSize} ${circleSize}`}>
          <circle
            stroke={circleBgColor}
            stroke-width={borderWidth}
            fill="transparent"
            cx={circleSize / 2}
            cy={circleSize / 2}
            r={Math.abs(circleSize / 2 - borderWidth / 2)}
          />
          <circle
            stroke={circleForeColor}
            stroke-width={percent > 0 ? borderWidth : 0}
            fill="transparent"
            stroke-dasharray={strokeDasharray}
            transform={`matrix(0, -1, 1, 0, 0, ${circleSize})`}
            stroke-linecap="round"
            fill-rule="nonzero"
            stroke-linejoin="round"
            cx={circleSize / 2}
            cy={circleSize / 2}
            r={Math.abs(circleSize / 2 - borderWidth / 2)}
            style={progressAnimation(percent, true)}
          />
        </svg>
        {this.renderPercentInfo()}
      </div>
    );
  }

  private renderProgressBar() {
    const { percent, status, variant } = this;
    const size = this.size === 'xs' ? 'sm' : this.size;
    return (
      <div class={classnames(prefix, `${prefix}--${size}`, `${prefix}--${variant}`)} part="base">
        <div class={`${prefix}__outer`} style={{ backgroundColor: COLORS.stroke }}>
          <div
            class={classnames(`${prefix}__inner`, `${prefix}__inner--${status}`)}
            style={{ width: `${percent}%`, backgroundColor: COLORS[status] }}
          />
        </div>
        {this.renderPercentInfo()}
      </div>
    );
  }

  render() {
    const { helpText, status, variant, width } = this;
    const barStyle = { width: width === undefined ? '' : convertNum2PX(width) };
    return (
      <Host style={variant === 'bar' ? barStyle : {}} class="KsProgress">
        {variant === 'ring' ? this.renderProgressRing() : this.renderProgressBar()}
        {helpText && variant === 'bar' && (
          <div class={classnames('helpText', status)}>
            <slot name="helpText"></slot>
          </div>
        )}
      </Host>
    );
  }
}
